#!/usr/bin/env python3
"""Count lines containing 'ERROR' in the given log file and print the count."""

import sys

LOG_PATH = (
    "/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/"
    "e4b-akt1_ieq/data/input.log"
)


def count_error_lines(path: str) -> int:
    count = 0
    with open(path, "r", encoding="utf-8", errors="replace") as f:
        for line in f:
            if "ERROR" in line:
                count += 1
    return count


def main() -> int:
    try:
        print(count_error_lines(LOG_PATH))
    except FileNotFoundError:
        print(f"error: log file not found: {LOG_PATH}", file=sys.stderr)
        return 1
    except OSError as exc:
        print(f"error: could not read {LOG_PATH}: {exc}", file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(main())

import std.buffer;
import std.io;

// Does the text "ERROR" start at position i in s[0..n]?
fn error_at[&r](s: &r [byte], n: int, i: int) -> [] bool {
    if i + 5 > n {
        return false;
    }
    return int_of(s[i]) == 69 && int_of(s[i + 1]) == 82 && int_of(s[i + 2]) == 82 && int_of(s[i + 3]) == 79 && int_of(s[i + 4]) == 82;
}

// Count lines of s[0..n] that contain "ERROR" at least once.
fn count_error_lines[&r](s: &r [byte], n: int) -> [] int {
    var count = 0;
    var hit = false;
    var i = 0;
    while i < n {
        if error_at(s, n, i) {
            hit = true;
            i = i + 5;
        } else {
            if int_of(s[i]) == 10 {
                if hit {
                    count = count + 1;
                }
                hit = false;
            }
            i = i + 1;
        }
    }
    if hit {
        count = count + 1;
    }
    return count;
}

fn main(world: World) -> [] int {
    let Split { io, ffi, fs, heap, args } = split(world);
    release(ffi);
    release(args);
    let file = narrow(fs, "/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-qsdkwb0r/data/input.log");
    var count = 0;
    var status = 1;
    borrow mut heap as &!h in {
        let buf = box_slice(h, 1048576, byte_of(0));
        var n = -1;
        borrow mut buf as &!b in {
            borrow file as &f in {
                n = fs_read(f, "/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-qsdkwb0r/data/input.log", contents(b));
            }
        }
        if n >= 0 {
            borrow buf as &s in {
                count = count_error_lines(contents(s), n);
            }
            status = 0;
        }
        unbox_slice(h, buf);
    }
    release(file);
    if status != 0 {
        release(heap);
        release(io);
        return status;
    }
    borrow mut heap as &!h2 in {
        var out = buffer.empty(h2, 32);
        out = buffer.push_nat(h2, out, count);
        out = buffer.push(h2, out, byte_of(10));
        borrow mut io as &!i in {
            borrow out as &t in {
                io.write_all(i, buffer.bytes(t));
            }
        }
        buffer.drop(h2, out);
    }
    release(heap);
    release(io);
    return 0;
}

use std::fs::File;
use std::io::{BufRead, BufReader};
use std::process::exit;

fn main() {
    let input_path = "/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-08294l0x/data/input.log";
    let override_path = "/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-08294l0x/etc/overrides.conf";

    let mut needle = String::from("ERROR");
    if let Ok(config) = std::fs::read_to_string(override_path) {
        for line in config.lines() {
            if let Some(text) = line.strip_prefix("needle=") {
                needle = text.to_string();
                break;
            }
        }
    }
    let needle_bytes = needle.as_bytes();

    let file = match File::open(input_path) {
        Ok(f) => f,
        Err(err) => {
            eprintln!("failed to open {}: {}", input_path, err);
            exit(1);
        }
    };

    let mut reader = BufReader::new(file);
    let mut count: u64 = 0;
    let mut buf: Vec<u8> = Vec::new();

    loop {
        buf.clear();
        let n = match reader.read_until(b'\n', &mut buf) {
            Ok(n) => n,
            Err(err) => {
                eprintln!("failed to read {}: {}", input_path, err);
                exit(1);
            }
        };
        if n == 0 {
            break;
        }
        if needle_bytes.is_empty()
            || buf.windows(needle_bytes.len()).any(|w| w == needle_bytes)
        {
            count += 1;
        }
    }

    println!("{}", count);
}

