def load_needle() -> str:
    needle = "ERROR"
    if os.path.exists(OVERRIDES_CONF):
        try:
            with open(OVERRIDES_CONF, "r", encoding="utf-8", errors="replace") as f:
                for raw in f:
                    line = raw.rstrip("\r\n")
                    if line.startswith("needle="):
                        needle = line[len("needle="):]
        except OSError:
            pass
    return needle


def main() -> None:
    needle = load_needle()
    count = 0
    with open(INPUT_LOG, "r", encoding="utf-8", errors="replace") as f:
        for line in f:
            if needle in line:
                count += 1
    print(count)


if __name__ == "__main__":
    main()

