import std.buffer;
import std.io;

// Count the lines in `data` that contain the text "ERROR".
fn count_error_lines[&r](data: &r [byte]) -> [] int {
    var count = 0;
    var matched = false;
    var w0 = 0;
    var w1 = 0;
    var w2 = 0;
    var w3 = 0;
    var w4 = 0;
    var i = 0;
    while i < len(data) {
        let c = int_of(data[i]);
        w0 = w1;
        w1 = w2;
        w2 = w3;
        w3 = w4;
        w4 = c;
        if w0 == 69 && w1 == 82 && w2 == 82 && w3 == 79 && w4 == 82 {
            matched = true;
        }
        if c == 10 {
            if matched {
                count = count + 1;
            }
            matched = false;
        }
        i = i + 1;
    }
    if len(data) > 0 && int_of(data[len(data) - 1]) != 10 && matched {
        count = count + 1;
    }
    return count;
}

fn main(world: World) -> [] int {
    let Split { io, ffi, fs, heap, args } = split(world);
    release(ffi);
    release(args);
    let log = narrow(fs, "/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-aqrxyrdj/data/input.log");
    var count = 0;
    var status = 0;
    borrow log as &f in {
        borrow mut heap as &!h in {
            var cap = 65536;
            var done = false;
            while !done {
                let buf = box_slice(h, cap, byte_of(0));
                var got = 0;
                borrow mut buf as &!b in {
                    got = fs_read(f, "/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-aqrxyrdj/data/input.log", contents(b));
                }
                if got < 0 {
                    status = 1;
                    done = true;
                } else if got < cap || cap >= 16777216 {
                    borrow buf as &r in {
                        count = count_error_lines(contents(r)[0..got]);
                    }
                    done = true;
                } else {
                    cap = cap * 2;
                }
                unbox_slice(h, buf);
            }
        }
    }
    release(log);
    borrow mut io as &!i in {
        borrow mut heap as &!h in {
            var out = buffer.empty(h, 32);
            out = buffer.push_nat(h, out, count);
            out = buffer.push(h, out, byte_of(10));
            borrow out as &t in {
                if io.write_all(i, buffer.bytes(t)) < 0 {
                    status = 2;
                }
            }
            buffer.drop(h, out);
        }
    }
    release(heap);
    release(io);
    return status;
}

