import std.buffer;
import std.io;

// The k-th character of the marker "ERROR", as an int (k is in 0..4).
fn pattern_at(k: int) -> [] int {
    if k == 0 { return 'E'; }
    if k == 3 { return 'O'; }
    return 'R';
}

fn main(world: World) -> [] int {
    let Split { io, ffi, fs, heap, args, net, clock, signals } = split(world);
    release(ffi); release(net); release(clock); release(signals);

    let log_path = "/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-sufa451d/data/input.log";
    let root = narrow(fs, "/");
    var count = 0;

    borrow root as &f in {
        borrow mut heap as &!h in {
            // Read the whole log into one heap buffer.
            let chunk = box_slice(h, 1048576, byte_of(0));
            var n = 0;
            borrow mut chunk as &!w in {
                n = fs_read(f, log_path, contents(w));
            }
            // Count the lines that contain "ERROR" (state lives across the
            // whole buffer, so a marker is always seen whole).
            borrow chunk as &r in {
                let buf = contents(r);
                var i = 0;
                var k = 0;
                var has = false;
                while i < n {
                    let v = int_of(buf[i]);
                    if v == 10 {
                        if has { count = count + 1; }
                        has = false;
                        k = 0;
                    } else if v == pattern_at(k) {
                        k = k + 1;
                        if k == 5 { has = true; k = 0; }
                    } else if v == 'E' {
                        k = 1;
                    } else {
                        k = 0;
                    }
                    i = i + 1;
                }
                if has { count = count + 1; }
            }
            unbox_slice(h, chunk);

            // The answer, as one line of text: "N\n".
            var line = buffer.empty(h, 16);
            line = buffer.push_nat(h, line, count);
            line = buffer.push(h, line, byte_of(10));

            borrow mut io as &!i in {
                borrow line as &t in {
                    io.write_all(i, buffer.bytes(t));
                }
            }

            // Scheduler contract: the cache directory is the first command
            // line argument; the result goes to result.txt inside it.
            borrow args as &g in {
                if arg_count(g) > 1 {
                    var out_path = buffer.empty(h, 512);
                    out_path = buffer.append(h, out_path, arg(g, 1));
                    out_path = buffer.append(h, out_path, "/result.txt");
                    borrow out_path as &p in {
                        borrow line as &t in {
                            fs_write(f, buffer.bytes(p), buffer.bytes(t));
                        }
                    }
                    buffer.drop(h, out_path);
                }
            }

            buffer.drop(h, line);
        }
    }

    release(root);
    release(io);
    release(heap);
    release(args);
    return 0;
}

