import std.buffer;
import std.dirs;
import std.io;

// One step of matching the text ERROR (E=69, R=82, O=79) across byte
// boundaries. Returns 5 on a full match, otherwise the next prefix length.
fn step(k: int, c: int) -> [] int {
    if k == 0 {
        if c == 69 { return 1; }
        return 0;
    }
    if k == 1 {
        if c == 82 { return 2; }
        if c == 69 { return 1; }
        return 0;
    }
    if k == 2 {
        if c == 82 { return 3; }
        if c == 69 { return 1; }
        return 0;
    }
    if k == 3 {
        if c == 79 { return 4; }
        if c == 69 { return 1; }
        return 0;
    }
    if c == 82 { return 5; }
    if c == 69 { return 1; }
    return 0;
}

