                                borrow mut fh as &!hnd in {
                                    var done = false;
                                    while !done {
                                        match file_read(hnd, chunk) {
                                            Read::Got(n) => {
                                                var i = 0;
                                                while i < n {
                                                    let c = int_of(chunk[i]);
                                                    if c == 10 {
                                                        if hit { count = count + 1; }
                                                        k = 0;
                                                        hit = false;
                                                    } else {
                                                        let nk = step(k, c);
                                                        if nk == 5 {
                                                            hit = true;
                                                            k = 0;
                                                        } else {
                                                            k = nk;
                                                        }
                                                    }
                                                    i = i + 1;
                                                }
                                            }
                                            Read::End => {
                                                if hit { count = count + 1; }
                                                done = true;
                                            }
                                            Read::Failed(e) => {
                                                status = 2;
                                                done = true;
                                            }
                                        }
                                    }
                                }
                            }
                            file_close(fh);
                            borrow mut heap as &!h in {
