fn contains[&r, &n](hay: &r [byte], needle: &n [byte]) -> [] bool {
    var nlen = len(needle);
    if nlen == 0 {
        return true;
    }
    if nlen > len(hay) {
        return false;
    }
    var i = 0;
    while i + nlen <= len(hay) {
        var j = 0;
        while j < nlen && int_of(hay[i + j]) == int_of(needle[j]) {
            j = j + 1;
        }
        if j == nlen {
            return true;
        }
        i = i + 1;
    }
    return false;
}

fn needle_of[&r](data: &r [byte]) -> [] &r [byte] {
    var line_start = 0;
    while line_start < len(data) {
