// True when the five bytes starting at position i spell "ERROR"
// (E=69, R=82, R=82, O=79, R=82).
fn is_err_at[&r](s: &r [byte], i: int) -> [] bool {
    if i + 5 > len(s) {
        return false;
    }
    if int_of(s[i]) != 69 {
        return false;
    }
    if int_of(s[i + 1]) != 82 {
        return false;
    }
    if int_of(s[i + 2]) != 82 {
        return false;
    }
    if int_of(s[i + 3]) != 79 {
        return false;
    }
    if int_of(s[i + 4]) != 82 {
        return false;
    }
    return true;
}

// Number of lines in s that contain "ERROR". A line with several
// occurrences counts once; a final line with no newline still counts.
fn count_errors[&r](s: &r [byte]) -> [] int {
    var count = 0;
    var has = false;
    var i = 0;
    while i < len(s) {
        if is_err_at(s, i) {
            has = true;
            i = i + 5;
        } else {
            if int_of(s[i]) == 10 {
                if has {
                    count = count + 1;
                }
                has = false;
            }
            i = i + 1;
        }
    }
    if has {
        count = count + 1;
    }
    return count;
}

