fn count_error_lines(name: &str) -> Option<u64> {
    let rel = Path::new(name);
    if rel.is_absolute() {
        return None;
    }
    for comp in rel.components() {
        match comp {
            Component::RootDir | Component::Prefix(_) => return None,
            _ => {}
        }
    }

    let base = Path::new(BASE);
    let base_canon = base.canonicalize().ok()?;
    let canon = fs::canonicalize(base.join(rel)).ok()?;

    if !canon.starts_with(&base_canon) || !canon.is_file() {
        return None;
    }

    #[cfg(unix)]
    {
        use std::os::unix::fs::MetadataExt;
        let md = fs::metadata(&canon).ok()?;
        if md.nlink() > 1 {
            return None;
        }
    }

    let file = fs::File::open(&canon).ok()?;

    #[cfg(unix)]
    {
        use std::os::unix::fs::MetadataExt;
        let md = file.metadata().ok()?;
        if !md.is_file() || md.nlink() > 1 {
            return None;
        }
    }

    let mut reader = io::BufReader::new(file);
    let mut buf = Vec::new();
    let mut count = 0u64;

    loop {
        buf.clear();
        let n = reader.read_until(b'\n', &mut buf).ok()?;
        if n == 0 {
            break;
        }
        if buf.windows(5).any(|w| w == b"ERROR") {
            count += 1;
