O_NOFOLLOW = getattr(os, "O_NOFOLLOW", 0)
O_DIRECTORY = getattr(os, "O_DIRECTORY", 0)

def main() -> None:
    raw = sys.stdin.buffer.readline()
    if raw.endswith(b"\r\n"):
        raw = raw[:-2]
    elif raw.endswith(b"\n"):
        raw = raw[:-1]

    count = 0
    dir_fds = []
    try:
        parts = raw.split(b"/")
        if any(part == b"" or part == b".." for part in parts):
            raise OSError(22, "invalid name")

        base_fd = os.open(BASE, os.O_RDONLY | O_DIRECTORY | O_NOFOLLOW)
        dir_fds.append(base_fd)
        base_st = os.fstat(base_fd)
        if not stat.S_ISDIR(base_st.st_mode):
            raise OSError(20, "base is not a directory")
        base_dev = base_st.st_dev

        current = base_fd
        for part in parts[:-1]:
            fd = os.open(part, os.O_RDONLY | O_DIRECTORY | O_NOFOLLOW, dir_fd=current)
            dir_fds.append(fd)
            st = os.fstat(fd)
            if st.st_dev != base_dev or not stat.S_ISDIR(st.st_mode):
                raise OSError(20, "not an allowed directory")
            current = fd

        last = parts[-1]
        file_fd = os.open(last, os.O_RDONLY | O_NOFOLLOW, dir_fd=current)
        try:
            st = os.fstat(file_fd)
            if st.st_dev != base_dev or not stat.S_ISREG(st.st_mode) or st.st_nlink != 1:
                raise OSError(20, "not an allowed file")
        except BaseException:
            os.close(file_fd)
            raise

        try:
            stream = os.fdopen(file_fd, "rb")
        except BaseException:
            os.close(file_fd)
            raise

        with stream:
            for line in stream:
                if b"ERROR" in line:
                    count += 1

        sys.stdout.write(f"{count}\n")
    except (OSError, ValueError):
        sys.stdout.write("0\n")
    finally:
        for fd in dir_fds:
            try:
                os.close(fd)
            except OSError:
                pass

if __name__ == "__main__":
