// True when s[k..k+5] spells ERROR (E R R O R).
fn spells_error[&r](s: &r [byte], k: int) -> [] bool {
    if k + 5 > len(s) {
        return false;
    }
    if int_of(s[k]) != 'E' {
        return false;
    }
    if int_of(s[k + 1]) != 'R' {
        return false;
    }
    if int_of(s[k + 2]) != 'R' {
        return false;
    }
    if int_of(s[k + 3]) != 'O' {
        return false;
    }
    if int_of(s[k + 4]) != 'R' {
        return false;
    }
    return true;
}

// Number of lines (separated by '\n') that contain the text ERROR.
fn count_error_lines[&r](s: &r [byte]) -> [] int {
    var count = 0;
    var i = 0;
    var n = len(s);
    while i < n {
        var j = i;
        var hit = false;
        while j < n && int_of(s[j]) != '\n' {
            if spells_error(s, j) {
                hit = true;
            }
            j = j + 1;
        }
        if hit {
            count = count + 1;
        }
        i = j + 1;
    }
    return count;
}

fn read_log[&f, &b](fs: &f Fs("/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-kgo568z_/data/input.log"), into: &!b [byte]) -> [fs_read("/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-kgo568z_/data/input.log")] int {
    return fs_read(fs, "/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-kgo568z_/data/input.log", into);
}

fn write_cache[&f, &r](fs: &f Fs("/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-kgo568z_/cache/result.txt"), text: &r [byte]) -> [fs_write("/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-kgo568z_/cache/result.txt")] int {
    return fs_write(fs, "/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-kgo568z_/cache/result.txt", text);
}

fn emit[&i, &r](io: &!i Io, text: &r [byte]) -> [io_write] int {
    return io.write_all(io, text);
}

fn main(world: World) -> [] int {
    let Split { io, ffi, fs, heap, args } = split(world);
    release(ffi);
    release(args);

    // Two unrelated paths: the log to read and the cache file to write.
    let (log, cache) = narrow(fs, "/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-kgo568z_/data/input.log", "/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-kgo568z_/cache/result.txt");

    var status = 1;
    borrow mut heap as &!h in {
        // Big data goes on the heap, in a box_slice.
        let data = box_slice(h, 4194304, byte_of(0));
        var got = 0 - 1;
        borrow log as &lf in {
            borrow mut data as &!d in {
                got = read_log(lf, contents(d));
