        }
        var count = 0;
        if got >= 0 {
            borrow data as &r in {
                count = count_error_lines(contents(r));
            }
            status = 0;
        }
        unbox_slice(h, data);

        // "N\n" goes to stdout and to the CI cache file alike.
        var text = buffer.empty(h, 24);
        text = buffer.push_nat(h, text, count);
        text = buffer.push(h, text, byte_of('\n'));
        borrow mut io as &!i in {
