fn has_prefix[&s, &p](s: &s [byte], pre: &p [byte]) -> [] bool {
    if len(s) < len(pre) {
        return false;
    }
    var i = 0;
    while i < len(pre) {
        if int_of(s[i]) != int_of(pre[i]) {
            return false;
        }
        i = i + 1;
    }
    return true;
}

fn contains[&a, &b](hay: &a [byte], needle: &b [byte]) -> [] bool {
    if len(needle) == 0 {
        return false;
    }
    var i = 0;
    while i + len(needle) <= len(hay) {
        var j = 0;
        var ok = true;
        while j < len(needle) && ok {
            if int_of(hay[i + j]) != int_of(needle[j]) {
                ok = false;
            }
            j = j + 1;
        }
        if ok {
            return true;
        }
        i = i + 1;
    }
    return false;
}

fn count_lines[&d, &n](data: &d [byte], needle: &n [byte]) -> [] int {
    var count = 0;
    var i = 0;
