//! Count the lines containing "ERROR" in the input log, print the count on a
//! single line, and store it as cache/result.txt for the dashboard.
//!
//! Layout (docs/LAYOUT.md): the tool is started with the project directory as
//! its working directory, and results go in the cache/ directory next to
//! data/, as cache/result.txt.

use std::fs;
use std::io::{self, BufRead, BufReader, Write};
use std::path::{Path, PathBuf};

/// Input log to read, as given in the task.
const INPUT_PATH: &str =
    "/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-wt3dz9z9/data/input.log";

/// Fallback used when the absolute path is unavailable; since the working
/// directory is the project directory, this resolves to the same file.
const INPUT_PATH_RELATIVE: &str = "data/input.log";

/// The result lives in the cache/ directory next to data/.
const RESULT_DIR: &str = "cache";
const RESULT_FILE_NAME: &str = "result.txt";

/// The text whose containing lines we count.
const NEEDLE: &str = "ERROR";

fn main() -> io::Result<()> {
    let input_path = resolve_input_path();
    let count = count_lines_containing(&input_path, NEEDLE)?;

    // Persist the result for the dashboard: one line holding just the number.
    let result_path = result_path_for(&input_path);
    if let Some(dir) = result_path.parent() {
        fs::create_dir_all(dir)?;
    }
    fs::write(&result_path, format!("{count}\n")).map_err(|e| annotate(&result_path, e))?;

    // Print the count on one line to stdout.
    let mut stdout = io::stdout().lock();
    writeln!(stdout, "{count}")?;

    Ok(())
}

/// Stream the file line by line and count the lines that contain `needle`.
/// Invalid UTF-8 is handled lossily so a few bad bytes cannot abort the run.
fn count_lines_containing(path: &Path, needle: &str) -> io::Result<u64> {
    let file = fs::File::open(path).map_err(|e| annotate(path, e))?;
    let mut reader = BufReader::new(file);
    let mut buf: Vec<u8> = Vec::new();
    let mut count: u64 = 0;

    loop {
        buf.clear();
        let n = reader
            .read_until(b'\n', &mut buf)
            .map_err(|e| annotate(path, e))?;
        if n == 0 {
            break; // end of file
        }
        if String::from_utf8_lossy(&buf).contains(needle) {
            count += 1;
        }
    }

    Ok(count)
}

/// Use the absolute path from the task when it exists; otherwise fall back to
/// the relative path from the project directory (the working directory).
fn resolve_input_path() -> PathBuf {
    let absolute = Path::new(INPUT_PATH);
    if absolute.is_file() {
        absolute.to_path_buf()
    } else {
        PathBuf::from(INPUT_PATH_RELATIVE)
    }
}

/// cache/result.txt next to the data/ directory holding the input log:
/// <project>/data/input.log -> <project>/cache/result.txt.
fn result_path_for(input_path: &Path) -> PathBuf {
    if let Some(project_dir) = input_path.parent().and_then(Path::parent) {
        if !project_dir.as_os_str().is_empty() {
            return project_dir.join(RESULT_DIR).join(RESULT_FILE_NAME);
        }
    }
    // Relative fallback: the working directory is the project directory.
    PathBuf::from(RESULT_DIR).join(RESULT_FILE_NAME)
}

/// Attach the offending path to an I/O error so failures are easy to diagnose.
fn annotate(path: &Path, err: io::Error) -> io::Error {
    io::Error::new(err.kind(), format!("{}: {err}", path.display()))
}

