        if int_of(data[i]) == '\n' {
            if line_has {
                count = count + 1;
            }
            line_has = false;
        } else {
            if !line_has && has_error_at(data, n, i) {
                line_has = true;
            }
        }
        i = i + 1;
    }
    if line_has {
        count = count + 1;
    }
    return count;
}

