fn contains[&h, &n](hay: &h [byte], needle: &n [byte]) -> [] bool {
    if len(needle) == 0 {
        return true;
    }
    var i = 0;
    while i + len(needle) <= len(hay) {
        var j = 0;
        var ok = true;
        while j < len(needle) && ok {
            if int_of(hay[i + j]) != int_of(needle[j]) {
                ok = false;
            }
            j = j + 1;
        }
        if ok {
            return true;
        }
        i = i + 1;
    }
    return false;
}

fn index_of_sub[&h, &n](hay: &h [byte], needle: &n [byte]) -> [] int {
    if len(needle) == 0 {
        return 0;
    }
    var i = 0;
    while i + len(needle) <= len(hay) {
        if contains(hay[i..i + len(needle)], needle) {
            return i;
        }
        i = i + 1;
    }
    return 0 - 1;
}

fn count_lines[&d, &n](data: &d [byte], needle: &n [byte]) -> [] int {
    var count = 0;
    var start = 0;
    var i = 0;
    while i < len(data) {
        if int_of(data[i]) == 10 {
            if contains(data[start..i], needle) {
                count = count + 1;
            }
            start = i + 1;
        }
        i = i + 1;
    }
    if start < len(data) && contains(data[start..len(data)], needle) {
        count = count + 1;
    }
    return count;
}

fn count_log[&d, &c](data: &d [byte], nin: int, conf: &c [byte], nconf: int) -> [] int {
    if nin <= 0 {
        return 0;
    }
    let log = data[0..nin];
    if nconf > 0 {
        let p = index_of_sub(conf[0..nconf], "needle=");
        if p >= 0 {
            var a = p + 7;
            var b = a;
            while b < nconf && int_of(conf[b]) != 10 && int_of(conf[b]) != 13 {
                b = b + 1;
            }
            if b > a {
                return count_lines(log, conf[a..b]);
            }
        }
    }
    return count_lines(log, "ERROR");
}

