fn count_in_file(path: &Path) -> io::Result<u64> {
    let file = fs::File::open(path)?;
    let reader = BufReader::new(file);
    let mut count = 0u64;
    for line in reader.split(b'\n') {
        let line = line?;
        if line.windows(5).any(|w| w == b"ERROR") {
            count += 1;
