fn walk(dir: &Path, total: &mut u64) {
    let entries = match fs::read_dir(dir) {
        Ok(e) => e,
        Err(_) => return,
    };
    for entry in entries.flatten() {
        let path = entry.path();
        let ft = match entry.file_type() {
            Ok(t) => t,
            Err(_) => continue,
        };
        if ft.is_dir() {
            walk(&path, total);
        } else if ft.is_file() {
            if let Ok(c) = count_in_file(&path) {
                *total += c;
            }
        }
    }
}

