_DIR_FLAGS = os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW | os.O_CLOEXEC
_FILE_FLAGS = os.O_RDONLY | os.O_NOFOLLOW | os.O_CLOEXEC


def open_inside(rel: bytes) -> Optional[int]:
    if not rel or rel.startswith(b"/") or b"\0" in rel or rel.endswith(b"/"):
        return None

    parts = rel.split(b"/")
    if any(part == b".." for part in parts):
        return None
    parts = [part for part in parts if part not in (b"", b".")]
    if not parts:
        return None

    try:
        base_fd = os.open(BASE, os.O_RDONLY | os.O_DIRECTORY)
    except OSError:
        return None

    open_dir_fds = [base_fd]
    try:
        cur = base_fd
        for part in parts[:-1]:
            nxt = os.open(part, _DIR_FLAGS, dir_fd=cur)
            open_dir_fds.append(nxt)
            cur = nxt

        fd = os.open(parts[-1], _FILE_FLAGS, dir_fd=cur)
        st = os.fstat(fd)
        if not stat.S_ISREG(st.st_mode) or st.st_nlink != 1:
            os.close(fd)
            return None
        return fd
    except OSError:
        return None
    finally:
        for old_fd in open_dir_fds:
            try:
                os.close(old_fd)
            except OSError:
                pass


