// Does the line buf[start..stop] contain needle?
fn line_has[&b, &q](buf: &b [byte], start: int, stop: int, needle: &q [byte]) -> [] bool {
    var nl = len(needle);
    if nl == 0 {
        return false;
    }
    var i = start;
    while i + nl <= stop {
        var j = 0;
        var ok = true;
        while j < nl && ok {
            if buf[i + j] != needle[j] {
                ok = false;
            }
            j = j + 1;
        }
        if ok {
            return true;
        }
        i = i + 1;
    }
    return false;
}

// Count the lines of buf[0..total] that contain needle.
fn count_lines[&b, &q](buf: &b [byte], total: int, needle: &q [byte]) -> [] int {
    var count = 0;
    var start = 0;
    var i = 0;
    while i < total {
        if buf[i] == byte_of(10) {
            if line_has(buf, start, i, needle) {
                count = count + 1;
            }
            start = i + 1;
        }
        i = i + 1;
    }
    // A last line with no trailing newline still counts.
    if start < total {
        if line_has(buf, start, total, needle) {
            count = count + 1;
        }
    }
    return count;
}

// The text after `needle=` on the first such line of buf[0..total],
// or an empty slice when there is none.
fn needle_from[&b](buf: &b [byte], total: int) -> [] &b [byte] {
    var prefix = "needle=";
    var i = 0;
    while i < total {
        var e = i;
        while e < total && buf[e] != byte_of(10) {
            e = e + 1;
        }
        var stop = e;
        if stop > i && buf[stop - 1] == byte_of(13) {
            stop = stop - 1;
        }
        if stop - i >= len(prefix) {
            var j = 0;
            var ok = true;
            while j < len(prefix) && ok {
                if buf[i + j] != prefix[j] {
                    ok = false;
                }
                j = j + 1;
            }
            if ok {
                return buf[i + len(prefix)..stop];
            }
        }
        i = e + 1;
    }
    return buf[0..0];
}

fn copy_of[&h, &r](heap: &!h Heap, s: &r [byte]) -> [heap] Box[[byte]] {
    let b = box_slice(heap, len(s), byte_of(0));
    borrow mut b as &!w in {
