import dirs.confined;

fn has_error[&r](s: &r [byte]) -> [] bool {
    var i = 0;
    while i + 4 < len(s) {
        if int_of(s[i]) == 69 && int_of(s[i + 1]) == 82 && int_of(s[i + 2]) == 82 && int_of(s[i + 3]) == 79 && int_of(s[i + 4]) == 82 {
            return true;
        }
        i = i + 1;
    }
    return false;
}

fn read_name[&h, &i](heap: &!h Heap, io: &!i Io) -> [heap, io_read] buffer.Buffer {
    var name = buffer.empty(heap, 64);
    var c = getchar(io);
    while c >= 0 && c != 10 && c != 13 {
        name = buffer.push(heap, name, byte_of(c));
        c = getchar(io);
    }
    return name;
}

fn count_file[&h, &d, &n](heap: &!h Heap, dir: &d Dir, name: &n [byte]) -> [heap, dir_read, file_read] int {
    match confined.open_file(dir, name) {
        Opened::Ok(file) => {
            var f = file;
            var total = 0;
            var line = buffer.empty(heap, 64);
            region a {
                let chunk = alloc_slice[a](4096, byte_of(0));
                var more = true;
                while more {
                    borrow mut f as &!fh in {
                        match file_read(fh, chunk) {
                            Read::Got(n) => {
                                var j = 0;
                                while j < n {
                                    if int_of(chunk[j]) == 10 {
                                        borrow line as &l in {
                                            if has_error(buffer.bytes(l)) {
                                                total = total + 1;
                                            }
                                        }
                                        buffer.drop(heap, line);
                                        line = buffer.empty(heap, 64);
                                    } else {
                                        line = buffer.push(heap, line, chunk[j]);
                                    }
                                    j = j + 1;
                                }
                            }
                            Read::End => {
                                more = false;
                            }
                            Read::Failed(e) => {
                                more = false;
                            }
                        }
                    }
                }
            }
            borrow line as &l in {
                if has_error(buffer.bytes(l)) {
                    total = total + 1;
                }
            }
            buffer.drop(heap, line);
            file_close(f);
            return total;
        }
        Opened::Failed(e) => {
            return 0;
        }
    }
}

fn emit[&h, &i](heap: &!h Heap, io: &!i Io, n: int) -> [heap, io_write] int {
    var out = buffer.empty(heap, 32);
    out = buffer.push_nat(heap, out, n);
    out = buffer.push(heap, out, byte_of(10));
    var written = 0;
    borrow out as &t in {
        written = io.write_all(io, buffer.bytes(t));
    }
    buffer.drop(heap, out);
    return written;
}

fn main(world: World) -> [] int {
    let Split { io, ffi, fs, heap, args, net, clock, signals } = split(world);
    release(ffi); release(args); release(net); release(clock); release(signals);
    borrow mut io as &!i in {
        borrow mut heap as &!h in {
            let name = read_name(h, i);
            let data = narrow(fs, "/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-tvjfgnud/data");
            var count = 0;
            borrow data as &f in {
                match open_dir(f, "/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-tvjfgnud/data") {
                    DirOpened::Ok(d) => {
                        var held = d;
                        borrow name as &t in {
                            borrow held as &dd in {
                                count = count_file(h, dd, buffer.bytes(t));
                            }
                        }
                        dir_close(held);
                    }
                    DirOpened::Failed(e) => {
                        count = 0;
                    }
                }
            }
            release(data);
            buffer.drop(h, name);
            emit(h, i, count);
