fn pat(j: int) -> [] int {
    if j == 0 { return 'E'; }
    if j == 1 { return 'R'; }
    if j == 2 { return 'R'; }
    if j == 3 { return 'O'; }
    return 'R';
}

fn count_error_lines[&r](s: &r [byte]) -> [] int {
    var count = 0;
    var j = 0;
    var line_has = false;
    var i = 0;
    while i < len(s) {
        let c = int_of(s[i]);
        if c == '\n' {
            if line_has { count = count + 1; }
            j = 0;
            line_has = false;
        } else {
            if c == pat(j) {
                j = j + 1;
                if j == 5 {
                    line_has = true;
                    j = 0;
                }
            } else {
                j = 0;
                if c == 'E' { j = 1; }
            }
        }
        i = i + 1;
    }
    if line_has { count = count + 1; }
    return count;
}

