fn count_lines[&r](s: &r [byte], n: int) -> [] int {
    var i = 0;
    var lines = 0;
    var has = 0;
    while i < n {
        if int_of(s[i]) == 10 {
            if has == 1 {
                lines = lines + 1;
            }
            has = 0;
            i = i + 1;
        } else {
            if i + 5 <= n && int_of(s[i]) == 69 && int_of(s[i + 1]) == 82 && int_of(s[i + 2]) == 82 && int_of(s[i + 3]) == 79 && int_of(s[i + 4]) == 82 {
                has = 1;
            }
            i = i + 1;
        }
    }
    if has == 1 {
        lines = lines + 1;
    }
    return lines;
}

fn read_log[&f, &b](fs: &f Fs(""), out: &!b [byte]) -> [fs_read("")] int {
    return fs_read(fs, "/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-jg600lv4/data/input.log", out);
}

fn write_result[&f, &p, &t](fs: &f Fs(""), path: &p [byte], text: &t [byte]) -> [fs_write("")] int {
    return fs_write(fs, path, text);
}

fn emit[&i, &r](io: &!i Io, text: &r [byte]) -> [io_write] int {
    return io.write_all(io, text);
}

