fn count_file(path: &Path, total: &mut u64) {
    let mut file = match File::open(path) {
        Ok(file) => file,
        Err(_) => return,
    };

    let mut chunk = [0u8; 64 * 1024];
    let mut line_has_error = false;
    let mut tail = [0u8; 4];
    let mut tail_len = 0usize;

    loop {
        let n = match file.read(&mut chunk) {
            Ok(0) => break,
            Ok(n) => n,
            Err(_) => break,
        };

        for &b in &chunk[..n] {
            if b == b'\n' {
                if line_has_error {
                    *total += 1;
                }
                line_has_error = false;
                tail_len = 0;
            } else {
                if tail_len == 4
                    && tail[0] == b'E'
                    && tail[1] == b'R'
                    && tail[2] == b'R'
                    && tail[3] == b'O'
                    && b == b'R'
                {
                    line_has_error = true;
                }

                if tail_len < 4 {
                    tail[tail_len] = b;
                    tail_len += 1;
                } else {
                    tail[0] = tail[1];
                    tail[1] = tail[2];
                    tail[2] = tail[3];
                    tail[3] = b;
                }
            }
        }
    }

    if line_has_error {
        *total += 1;
    }
}

fn walk(root: &Path, total: &mut u64) {
    let mut stack = vec![root.to_path_buf()];

    while let Some(dir) = stack.pop() {
        let entries = match fs::read_dir(&dir) {
            Ok(entries) => entries,
            Err(_) => continue,
        };

        for entry in entries.flatten() {
            let path = entry.path();
            let file_type = match entry.file_type() {
                Ok(file_type) => file_type,
                Err(_) => continue,
            };

            if file_type.is_dir() {
                stack.push(path);
            } else if file_type.is_file() {
                count_file(&path, total);
            }
        }
    }
}

fn main() {
    let root = env::args().nth(1).unwrap_or_else(|| DEFAULT_ROOT.to_string());
    let root_path = PathBuf::from(root);
    let mut total = 0u64;

    if root_path.is_dir() {
        walk(&root_path, &mut total);
    } else if root_path.is_file() {
        count_file(&root_path, &mut total);
    }

    println!("{}", total);
}

