use std::path::Path;

const BASE: &str = "/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-7_v69je0/data";

fn contains_error(buf: &[u8]) -> bool {
    buf.windows(5).any(|w| w == &b"ERROR"[..])
}

fn count_error_lines(name: &str) -> io::Result<u64> {
    let base = fs::canonicalize(BASE)?;
    if name.is_empty() {
        return Ok(0);
    }

    let candidate = Path::new(BASE).join(name);
    let resolved = fs::canonicalize(&candidate)?;

    // Component-aware prefix check: /data must not match /data_evil.
    if !resolved.starts_with(&base) {
        return Ok(0);
    }

    let file = fs::File::open(&resolved)?;
    let md = file.metadata()?;
    if !md.is_file() {
        return Ok(0);
    }

    // A hard link to a file elsewhere gives the inode more than one link.
    // Refuse ambiguous cases rather than risk reading outside BASE.
    #[cfg(unix)]
    {
        use std::os::unix::fs::MetadataExt;
        if md.nlink() != 1 {
            return Ok(0);
        }
    }

    let mut reader = io::BufReader::new(file);
    let mut buf: Vec<u8> = Vec::new();
    let mut count: u64 = 0;

    loop {
        buf.clear();
        let n = reader.read_until(b'\n', &mut buf)?;
        if n == 0 {
            break;
        }
        if contains_error(&buf) {
            count += 1;
        }
    }

    Ok(count)
}

fn main() {
    let mut line = String::new();
    if io::stdin().read_line(&mut line).is_err() {
        println!("0");
        return;
    }

    let name = line.trim_end_matches(['\n', '\r']);
    let n = count_error_lines(name).unwrap_or(0);
    println!("{}", n);
}

