// Count the lines of "input.log" beneath `dir` that contain "ERROR".
// Reads in chunks, so a line (or an "ERROR") may span two reads.
fn count_error_lines[&d, &b](dir: &d Dir, into: &!b [byte]) -> [dir_read, file_read] int {
    var count = 0;
    var line_has = false;
    var matched = 0;
    let pat = "ERROR";
    match dirs.open_file(dir, "input.log") {
        Opened::Ok(file) => {
            var f = file;
            borrow mut f as &!h in {
                var done = false;
                while !done {
                    match file_read(h, into) {
                        Read::Got(n) => {
                            var i = 0;
                            while i < n {
                                let c = int_of(into[i]);
                                if c == 10 {
                                    if line_has { count = count + 1; }
                                    line_has = false;
                                    matched = 0;
                                } else if c == int_of(pat[matched]) {
                                    matched = matched + 1;
                                    if matched == len(pat) {
                                        line_has = true;
                                        matched = 0;
                                    }
                                } else if c == int_of(pat[0]) {
                                    matched = 1;
                                } else {
                                    matched = 0;
                                }
                                i = i + 1;
                            }
                        }
                        Read::End => {
                            if line_has { count = count + 1; }
                            done = true;
                        }
                        Read::Failed(e) => {
                            done = true;
                        }
                    }
                }
            }
            file_close(f);
        }
        Opened::Failed(e) => {
            count = 0 - 1;
        }
    }
    return count;
}

