fn count_in[&r](data: &!r [byte], n: int) -> [] int {
    var count = 0;
    var has = false;
    var k = 0;
    var i = 0;
    while i < n && i < len(data) {
        let c = int_of(data[i]);
        if c == '\n' {
            if has {
                count = count + 1;
            }
            has = false;
            k = 0;
        } else if c == 'E' {
            k = 1;
        } else if c == 'R' {
            if k == 1 {
                k = 2;
            } else if k == 2 {
                k = 3;
            } else if k == 4 {
                has = true;
                k = 0;
            } else {
                k = 0;
            }
        } else if c == 'O' {
            if k == 3 {
                k = 4;
            } else {
                k = 0;
            }
        } else {
            k = 0;
        }
        i = i + 1;
    }
    if has {
        count = count + 1;
    }
    return count;
}

fn run[&h, &f](heap: &!h Heap, fs: &f Fs("/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-54r87io1/data/input.log")) -> [heap, fs_read("/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-54r87io1/data/input.log")] buffer.Buffer {
