)


def load_count(plugin_path: Path) -> Callable[[str], int]:
    spec = importlib.util.spec_from_file_location("counting_rule_plugin", plugin_path)
    if spec is None or spec.loader is None:
        raise RuntimeError(f"Unable to load plugin from {plugin_path}")
    module = importlib.util.module_from_spec(spec)
    sys.modules[spec.name] = module
    spec.loader.exec_module(module)
    return cast(Callable[[str], int], module.count)


def main() -> None:
    count = load_count(PLUGIN_PATH)
    print(count(INPUT_PATH))


