fn has_error_at[&r](s: &r [byte], i: int) -> [] bool {
    if i + 4 >= len(s) {
        return false;
    }
    return int_of(s[i]) == 'E' && int_of(s[i + 1]) == 'R' && int_of(s[i + 2]) == 'R' && int_of(s[i + 3]) == 'O' && int_of(s[i + 4]) == 'R';
}

fn count_error_lines[&r](s: &r [byte]) -> [] int {
    var count = 0;
    var i = 0;
    var hit = false;
    while i < len(s) {
        if has_error_at(s, i) {
            hit = true;
        }
        if int_of(s[i]) == 10 {
            if hit {
                count = count + 1;
            }
            hit = false;
        }
        i = i + 1;
    }
