use std::fs::{self, File};
use std::io::{self, BufRead, BufReader};
use std::os::unix::fs::MetadataExt;
use std::path::Path;

const BASE: &str = "/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-e1veyr7x/data";

fn has_error(line: &[u8]) -> bool {
    line.windows(5).any(|w| w == b"ERROR")
}

fn count_errors() -> io::Result<usize> {
    let mut name = String::new();
    io::stdin().read_line(&mut name)?;

    while name.ends_with('\n') || name.ends_with('\r') {
        name.pop();
    }

    if name.is_empty() || name.contains('\0') {
        return Ok(0);
    }

    let rel = Path::new(&name);
    if rel.is_absolute() {
        return Ok(0);
    }

    let base = Path::new(BASE);
    let base_real = fs::canonicalize(base)?;
    let real = fs::canonicalize(base.join(rel))?;

    if !real.starts_with(&base_real) {
        return Ok(0);
    }

    let meta = fs::metadata(&real)?;
    if !meta.is_file() || meta.nlink() > 1 {
        return Ok(0);
    }

    let file = File::open(&real)?;
    let mut reader = BufReader::new(file);
    let mut count = 0usize;
    let mut buf: Vec<u8> = Vec::new();

    loop {
        buf.clear();
        let n = reader.read_until(b'\n', &mut buf)?;
        if n == 0 {
            break;
        }
        if has_error(&buf) {
            count += 1;
        }
    }

    Ok(count)
}

fn main() {
    let count = count_errors().unwrap_or(0);
    println!("{}", count);
}

